import{_ as e,C as r,c as i,o as l,a0 as t,b as n,w as a,a as o,G as s,a1 as d}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Træningslejr: Weekendguide","description":"","frontmatter":{},"headers":[],"relativePath":"da/training-camp.md","filePath":"da/training-camp.md"}');const u=e({name:"da/training-camp.md"},[["render",function(e,g,u,k,p,m){const f=r("Mermaid");return l(),i("div",null,[g[2]||(g[2]=t('<h1 id="træningslejr-weekendguide" tabindex="-1">Træningslejr: Weekendguide <a class="header-anchor" href="#træningslejr-weekendguide" aria-label="Permalink to &quot;Træningslejr: Weekendguide&quot;">​</a></h1><h2 id="sadan-afholder-du-en-weekendtræningslejr-for-10-20-spillere" tabindex="-1">Sådan afholder du en weekendtræningslejr for 10-20 spillere <a class="header-anchor" href="#sadan-afholder-du-en-weekendtræningslejr-for-10-20-spillere" aria-label="Permalink to &quot;Sådan afholder du en weekendtræningslejr for 10-20 spillere&quot;">​</a></h2><p>Denne omfattende guide hjælper dig med at organisere og afholde en weekendtræningslejr, der kombinerer teori, praksis og konkurrence. Bland det mentale spilindhold fra denne hjemmeside med træning på pisten for maksimal effekt.</p><div class="tip custom-block"><p class="custom-block-title">Træningslejrfilosofien</p><p><strong>Teori uden praksis er blot information. Øvelse uden teori er blot gentagelse. Konkurrence uden refleksion er blot leg.</strong> Denne weekend integrerer alle tre for transformerende læring.</p></div>',4)),(l(),n(d,null,{default:a(()=>[s(f,{id:"mermaid-14",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWeekend%20Camp%5D%20--%3E%20B%5BFriday%3A%20Theory%5D%0A%20%20%20%20B%20--%3E%20C%5BSaturday%3A%20Practice%5D%0A%20%20%20%20C%20--%3E%20D%5BSunday%3A%20Competition%5D%0A%20%20%20%20D%20--%3E%20E%5BIntegration%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:a(()=>[...g[0]||(g[0]=[o(" Loading... ",-1)])]),_:1})),g[3]||(g[3]=t('<h2 id="planlægning-før-lejren" tabindex="-1">Planlægning før lejren <a class="header-anchor" href="#planlægning-før-lejren" aria-label="Permalink to &quot;Planlægning før lejren&quot;">​</a></h2><h3 id="gruppestørrelse-og-struktur" tabindex="-1">Gruppestørrelse og -struktur <a class="header-anchor" href="#gruppestørrelse-og-struktur" aria-label="Permalink to &quot;Gruppestørrelse og -struktur&quot;">​</a></h3><p><strong>Optimalt:</strong> 10-20 spillere</p><ul><li><strong>Lille lejr (10-12):</strong> Mere intim, dybere deling</li><li><strong>Stor lejr (16-20):</strong> Mere forskelligartede perspektiver, kræver undergrupper</li></ul><p><strong>Holdstruktur:</strong></p><ul><li>Opdel jer i hold på 3-4 til træning og konkurrence</li><li>Bland færdighedsniveauer og spillestile</li><li>Roter holdene i løbet af weekenden</li></ul><h3 id="personalekrav" tabindex="-1">Personalekrav <a class="header-anchor" href="#personalekrav" aria-label="Permalink to &quot;Personalekrav&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rolle</th><th>Ansvar</th><th>Mængde</th></tr></thead><tbody><tr><td><strong>Koordinator for mental præstation</strong></td><td>Facilitering af teorisessioner, gruppedynamik</td><td>1</td></tr><tr><td><strong>Teknisk træner</strong></td><td>Overvåge træning, give feedback</td><td>1-2</td></tr><tr><td><strong>Konkurrenceleder</strong></td><td>Afvikling af turnering, styring af logistik</td><td>1</td></tr><tr><td><strong>Supportpersonale</strong></td><td>Måltider, opsætning, administration</td><td>1-2</td></tr></tbody></table><h3 id="krav-til-placering" tabindex="-1">Krav til placering <a class="header-anchor" href="#krav-til-placering" aria-label="Permalink to &quot;Krav til placering&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Facilitetsbehov</p><p><strong>Piste:</strong></p><ul><li>Flere terræner (minimum 3-4 pister)</li><li>Forskellige overflader, hvis muligt (grus, sand, hårdt)</li><li>Belysning til aftenleg</li></ul><p><strong>Indendørs rum:</strong></p><ul><li>Plads til 20 personer i rundkreds (teoriundervisning)</li><li>Adskilt fra pisten</li><li>Whiteboard/projektor</li><li>Komfortable siddepladser</li></ul><p><strong>Indkvartering:</strong></p><ul><li>På stedet eller i nærheden (gåafstand)</li><li>Delte rum fremmer tilknytning</li><li>Stille rum til refleksion</li></ul><p><strong>Forplejning:</strong></p><ul><li>Ernæringsfokuserede måltider (se <a href="./food">Madguide</a>)</li><li>Undgå sukkerkrasj</li><li>Hydreringsstationer</li></ul></div><h3 id="materialecheckliste" tabindex="-1">Materialecheckliste <a class="header-anchor" href="#materialecheckliste" aria-label="Permalink to &quot;Materialecheckliste&quot;">​</a></h3><details class="details custom-block"><summary>Komplet materialeliste</summary><p><strong>Teoritimer:</strong></p><ul><li>[ ] Stole til rundkreds (ingen borde)</li><li>[ ] Boules og cochonnet til center</li><li>[ ] Flipovere og tuscher</li><li>[ ] Sticky notes</li><li>[ ] Arbejdsark (brugermanual, indre kritiker osv.)</li><li>[ ] Papir og kuglepenne</li><li>[ ] Projektor (til hjemmesideindhold)</li></ul><p><strong>Øvelsessessioner:</strong></p><ul><li>[ ] Målebånd</li><li>[ ] Kegler/markører til boremaskiner</li><li>[ ] Videokamera/stativ</li><li>[ ] Udklipsholder og papir (sporing)</li><li>[ ] Fløjte</li></ul><p><strong>Konkurrence:</strong></p><ul><li>[ ] Pointlister</li><li>[ ] Turneringsbracket</li><li>[ ] Præmier/anerkendelse</li><li>[ ] Førstehjælpskasse</li></ul><p><strong>Logistik:</strong></p><ul><li>[ ] Navneskilte</li><li>[ ] Deltagerliste med kontakter</li><li>[ ] Kontaktoplysninger i nødstilfælde</li><li>[ ] Vandflasker</li><li>[ ] Solcreme</li><li>[ ] Væv (til følelsesmæssigt arbejde!)</li></ul></details><h2 id="weekendplan" tabindex="-1">Weekendplan <a class="header-anchor" href="#weekendplan" aria-label="Permalink to &quot;Weekendplan&quot;">​</a></h2><h3 id="fredag-aften-3-timer" tabindex="-1">Fredag aften (3 timer) <a class="header-anchor" href="#fredag-aften-3-timer" aria-label="Permalink to &quot;Fredag aften (3 timer)&quot;">​</a></h3><p><strong>18:00-18:30 - Ankomst og velkomst</strong></p><ul><li>Indtjekning</li><li>Rumtildelinger</li><li>Oversigt over weekenden</li></ul><p><strong>18:30-19:30 - Aftensmad</strong></p><ul><li>Ernæringsfokuseret måltid</li><li>Uformelle introduktioner</li></ul><p><strong>19:30-22:30 - Teorisession: Grundlæggende</strong></p><p>Brug <a href="./workshop">Workshop-guiden</a> til detaljeret facilitering:</p><ol><li><strong>Grundregler (15 min)</strong> - Etabler psykologisk tryghed</li><li><strong>Check-in matrix (20 min)</strong> - Vurder gruppens energi</li><li><strong>Isbjerget (30 min)</strong> - Udforsk dine indre tanker</li><li><strong>Brugermanual (45 min)</strong> - Skab teamforståelse</li><li><strong>Frygt i en hat (45 min)</strong> - Bryd isolation</li><li><strong>Udtjekning (15 min)</strong> - Slut på løkken</li></ol><p><strong>22:30 - Fritid</strong></p><ul><li>Uformel socialisering</li><li>Hvile og refleksion</li></ul>',23)),(l(),n(d,null,{default:a(()=>[s(f,{id:"mermaid-439",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFriday%20Theory%5D%20--%3E%20B%5BPsychological%20Safety%5D%0A%20%20%20%20B%20--%3E%20C%5BSelf-Awareness%5D%0A%20%20%20%20C%20--%3E%20D%5BTeam%20Understanding%5D%0A%20%20%20%20D%20--%3E%20E%5BReady%20for%20Practice%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A"})]),fallback:a(()=>[...g[1]||(g[1]=[o(" Loading... ",-1)])]),_:1})),g[4]||(g[4]=t('<h3 id="lørdag-heldag-teori-praksis" tabindex="-1">Lørdag (Heldag - Teori + Praksis) <a class="header-anchor" href="#lørdag-heldag-teori-praksis" aria-label="Permalink to &quot;Lørdag (Heldag - Teori + Praksis)&quot;">​</a></h3><p><strong>08:00-09:00 - Morgenmad og mindfulness</strong></p><ul><li>Stille morgenmad</li><li>Valgfri 15-minutters guidet meditation</li><li>Sæt intentioner for dagen</li></ul><p><strong>09:00-10:30 - Teorisession: Forbindelse af indhold med oplevelse</strong></p><p>Vælg 3-4 emner fra Akademiets hjemmeside og udforsk det indre spil:</p><p><strong>Eksempler på emner:</strong></p><ol><li><p><strong><a href="./uddannelse/ernæring/">Ernæring</a></strong> (20 min)</p><ul><li>&quot;Hvordan ændrer dit madvalg sig under pres?&quot;</li><li>&quot;Spiser du, hvad din krop har brug for, eller hvad din angst ønsker?&quot;</li><li>Øvelse: Planlæg ernæring på konkurrencedagen</li></ul></li><li><p><strong><a href="./uddannelse/mental-styrke/">Mental styrke</a></strong> (25 min)</p><ul><li>&quot;Hvad er dit forhold til fiasko?&quot;</li><li>&quot;Hvordan taler du til dig selv efter en miss?&quot;</li><li>Aktivitet: Omformuler indre kritiker til indre coach</li></ul></li><li><p><strong><a href="./uddannelse/mindfulness/">Mindfulness</a></strong> (25 min)</p><ul><li>&quot;Hvor går dine tanker hen i pausen før du kaster?&quot;</li><li>&quot;Hvad trækker dig ud af nuet?&quot;</li><li>Øvelse: 5-minutters kropsscanning</li></ul></li><li><p><strong><a href="./uddannelse/taktik/">Taktik</a></strong> (20 min)</p><ul><li>&quot;Er dit slagvalg baseret på strategi eller frygt?&quot;</li><li>&quot;Hvornår spiller man sikkert vs. tager man risici?&quot;</li><li>Diskuter: Risikoprofiler i gruppen</li></ul></li></ol><p><strong>10:30-10:45 - Pause</strong></p><p><strong>10:45-12:30 - Integration på pisten: Øvelser med mentalt fokus</strong></p><p><strong>Øvelse 1: Tag dit skud (30 min)</strong></p><p>Fra <a href="./workshop">Workshop-guiden</a> - øv dig i at eje intention og tvivl:</p><ol><li>Annoncer målet: &quot;Jeg skyder med jernet&quot;</li><li>Selvtillid: &quot;Jeg får 7 ud af 10&quot;</li><li>Nævn den indre tanke: &quot;Min indre stemme bekymrer sig om bagspin&quot;</li><li>Udfør skuddet</li><li>Reflektér: &quot;Hvad skete der? Hvad lærte du?&quot;</li></ol><p><strong>Øvelse 2: Kognitiv interferens (30 min)</strong></p><p>Test om teknikken er blevet automatisk:</p><ul><li>Koordinator stiller komplekse spørgsmål, mens spilleren skyder</li><li>&quot;Nævn 5 hovedstæder&quot; eller &quot;Tæl baglæns fra 100 gange 7&quot;</li><li>Succes = teknik er implicit, ikke bevidst bearbejdet</li></ul><p><strong>Øvelse 3: Brugermanualøvelse (30 min)</strong></p><p>Anvend brugermanualerne fra fredag:</p><ul><li>Spil i hold af 3</li><li>Efter hvert skud reagerer holdkammeraterne i henhold til brugermanualen</li><li>&quot;Marc har brug for stilhed efter en misser&quot; - holdet ærer det</li><li>Opsummering: &quot;Hvordan føltes det at blive forstået?&quot;</li></ul><p><strong>12:30-14:00 - Frokost og hvile</strong></p><ul><li>Ernæringsfokuseret måltid</li><li>Stille tid til refleksion</li><li>Valgfrit: Individuelle indtjekninger med koordinator</li></ul><p><strong>14:00-17:00 - Træningssession: Terræntilpasning</strong></p><p><strong>Mål:</strong> Opbygge tilpasningsevne og mental fleksibilitet</p><p><strong>Opsætning:</strong></p><ul><li>Roter gennem 3-4 forskellige terræner/pister</li><li>45 minutter pr. terræn</li><li>Fokus på mental tilpasning, ikke kun teknisk</li></ul><p><strong>Rotationsstruktur:</strong></p><table tabindex="0"><thead><tr><th>Terræn</th><th>Mentalt fokus</th><th>Træning</th></tr></thead><tbody><tr><td><strong>Terræn 1: Blødt/Sand</strong></td><td>Accept af usikkerhed</td><td>&quot;Den uanede - accepter det, der er&quot;</td></tr><tr><td><strong>Terræn 2: Hårdt/Gruset</strong></td><td>Præcision under pres</td><td>&quot;Stol på din teknik&quot;</td></tr><tr><td><strong>Terræn 3: Ujævn</strong></td><td>Følelsesregulering</td><td>&quot;Bevar roen, når det er uretfærdigt&quot;</td></tr><tr><td><strong>Terræn 4: Konkurrence</strong></td><td>Adgang til flowtilstand</td><td>&quot;Find zonen&quot;</td></tr></tbody></table><p><strong>Facilitering:</strong></p><ul><li>Teknisk træner giver feedback på teknik</li><li>MPC spørger: &quot;Hvad sker der i dit hoved lige nu?&quot;</li><li>Spillerjournal mellem rotationer</li></ul><p><strong>17:00-18:00 - Pause og refleksion</strong></p><ul><li>Individuel journalføring</li><li>&quot;Hvad lærte du om dig selv i dag?&quot;</li><li>&quot;Hvad er én ting, du vil gøre anderledes i morgen?&quot;</li></ul><p><strong>18:00-19:00 - Aftensmad</strong></p><p><strong>19:00-21:00 - Aftenteori: Dyb sårbarhed</strong></p><p><strong>Aktivitet 1: Omformulering af den indre kritiker (45 min)</strong></p><p>Se <a href="./workshop">Workshop-vejledning</a> for den fulde protokol:</p><ol><li>Identificér den nøjagtige kritikerfrase</li><li>Omformuler som indre coach</li><li>Partnerpraksis</li></ol><p><strong>Aktivitet 2: Konkurrenceforberedelse (45 min.)</strong></p><p>I morgen er det konkurrencedag. Forbered dig mentalt:</p><ol><li><p><strong>Visualisering (15 min.)</strong></p><ul><li>Luk øjnene</li><li>Forestil dig det perfekte skud</li><li>Føl selvtilliden</li><li>Læg mærke til roen</li></ul></li><li><p><strong>Teamprotokoller (20 min.)</strong></p><ul><li>Skab signaler for støtte</li><li>&quot;Jeg har brug for en nulstilling&quot; = rør ved boules</li><li>&quot;Jeg har brug for opmuntring&quot; = knytnævestød</li><li>&quot;Jeg har brug for plads&quot; = et skridt tilbage</li></ul></li><li><p><strong>Sæt intentioner (10 min.)</strong></p><ul><li>&quot;I morgen vil jeg fokusere på...&quot;</li><li>&quot;Mit mål er ikke at vinde, men at...&quot;</li><li>&quot;Jeg vil øve mig...&quot;</li></ul></li></ol><p><strong>Udtjekning (30 min.)</strong></p><ul><li>Del én frygt om morgendagen</li><li>Del én intention</li><li>Gruppestøtte</li></ul><p><strong>21:00 - Fritid</strong></p><ul><li>Tidligt i seng (konkurrence i morgen!)</li><li>Stille refleksion</li></ul><h3 id="søndag-konkurrencedag" tabindex="-1">Søndag (konkurrencedag) <a class="header-anchor" href="#søndag-konkurrencedag" aria-label="Permalink to &quot;Søndag (konkurrencedag)&quot;">​</a></h3><p><strong>08:00-09:00 - Morgenmad og mental forberedelse</strong></p><ul><li>Let morgenmad (se <a href="./uddannelse/ernæring/">Ernæringsvejledning</a>)</li><li>15 minutters mindfulness-øvelse</li><li>Holdmøder</li></ul><p><strong>09:00-09:30 - Konkurrencebriefing</strong></p><p><strong>Format:</strong> Round-robin-turnering</p><ul><li>Hold på 3</li><li>Spil til 13 point</li><li>Alle spiller alle</li><li>Fokus på PROCES, ikke resultat</li></ul><p><strong>Twist: Mental præstationsscoring</strong></p><div class="tip custom-block"><p class="custom-block-title">dobbelt scoringssystem</p><p><strong>Traditionel:</strong> Point vundet <strong>Mental præstation:</strong> Bedømmelse foretaget af MPC</p><p>Mentale præstationspoint (0-5 pr. kamp):</p><ul><li>Brugte brugermanualværktøjer</li><li>Støttede effektivt holdkammerater</li><li>Håndteret indre kritiker</li><li>Forblev nærværende (ikke dvælende ved tidligere optagelser)</li><li>Dokumenteret psykologisk tryghed</li></ul><p><strong>Vinder:</strong> Bedste kombinerede score (traditionel + mental)</p></div><p><strong>09:30-13:00 - Morgenkonkurrence</strong></p><ul><li>Round-robin-spil</li><li>MPC observerer og scorer</li><li>Teknisk træner giver kort feedback mellem kampene</li><li>Hydrering og snackpauser</li></ul><p><strong>13:00-14:00 - Frokost</strong></p><ul><li>Ernæringsfokuseret</li><li>Uformel refleksion</li><li>Hvile</li></ul><p><strong>14:00-17:00 - Eftermiddagskonkurrence</strong></p><ul><li>Fortsæt round-robin</li><li>Semifinaler og finaler</li><li>Øget pres</li><li>Anvend morgenens læring</li></ul><p><strong>17:00-17:30 - Priser og anerkendelse</strong></p><p><strong>Kategorier:</strong></p><ul><li>Traditionel vinder</li><li>Vinder af mental præstation</li><li>Mest forbedret</li><li>Bedste holdkammerat</li><li>Modpris (mest sårbare)</li></ul><p><strong>17:30-19:00 - Afsluttende refleksionssession</strong></p><p><strong>Kritisk:</strong> Det er her, læring cementeres.</p><p><strong>Struktur:</strong></p><p><strong>1. Individuel refleksion (15 min.)</strong> Skriv i dagbogen:</p><ul><li>Hvad lærte du om dig selv i weekenden?</li><li>Hvad overraskede dig?</li><li>Hvad vil du gøre anderledes?</li><li>Hvad tager du med hjem?</li></ul><p><strong>2. Deling i små grupper (30 min)</strong> Grupper på 4-5:</p><ul><li>Del vigtige indsigter</li><li>Hvad gav mest genklang?</li><li>Hvad var sværest?</li><li>Hvad var mest værdifuldt?</li></ul><p><strong>3. Fuld gruppeintegration (30 min)</strong> Ring op:</p><ul><li>Hver person deler ÉN vigtig konklusion</li><li>MPC validerer og forbinder temaer</li><li>Diskuter: &quot;Hvordan vil I anvende dette?&quot;</li></ul><p><strong>4. Forpligtelser (15 min.)</strong></p><ul><li>Hver person forpligter sig én gang</li><li>&quot;I min næste konkurrence vil jeg...&quot;</li><li>Gruppevidner og støtter</li></ul><p><strong>5. Afslutning (15 min.)</strong></p><ul><li>Tak deltagerne for modet</li><li>Mind om fortrolighed</li><li>Udveksle kontakter</li><li>Planlæg opfølgning (valgfri online session)</li></ul><p><strong>19:00 - Aftensmad og afrejse</strong></p><h2 id="tips-til-facilitering" tabindex="-1">Tips til facilitering <a class="header-anchor" href="#tips-til-facilitering" aria-label="Permalink to &quot;Tips til facilitering&quot;">​</a></h2><h3 id="balancering-af-teori-og-praksis" tabindex="-1">Balancering af teori og praksis <a class="header-anchor" href="#balancering-af-teori-og-praksis" aria-label="Permalink to &quot;Balancering af teori og praksis&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Overbelast ikke teorien</p><p><strong>Fejlen:</strong> For meget snak, for lidt handling</p><p><strong>Restbeløbet:</strong></p><ul><li>Teori skaber bevidsthed</li><li>Øvelse opbygger færdigheder</li><li>Integration af konkurrencetests</li><li>Refleksion cementerer læring</li></ul><p><strong>Tommelfingerregel:</strong> 30% teori, 40% øvelse, 20% konkurrence, 10% refleksion</p></div><h3 id="handtering-af-gruppedynamik" tabindex="-1">Håndtering af gruppedynamik <a class="header-anchor" href="#handtering-af-gruppedynamik" aria-label="Permalink to &quot;Håndtering af gruppedynamik&quot;">​</a></h3><p><strong>Den konkurrencedygtige alfa:</strong></p><ul><li>Vil vinde for enhver pris</li><li>Modstår sårbarhed</li><li><strong>Strategi:</strong> Kanaliser konkurrenceevne ind i mental præstationsscoring</li></ul><p><strong>Den stille iagttager:</strong></p><ul><li>Tager det hele ind, deler ikke</li><li><strong>Strategi:</strong> Skab indgangspunkter med lav risiko, valider observation som deltagelse</li></ul><p><strong>Skeptikeren:</strong></p><ul><li>&quot;Det her følsomme virkede ikke&quot;</li><li><strong>Strategi:</strong> Verbal Aikido - justere og dreje (se <a href="./workshop">Workshop guide</a>)</li></ul><p><strong>Den Overdelende:</strong></p><ul><li>Dominerer diskussionen</li><li><strong>Strategi:</strong> &quot;Tak, lad os høre fra andre&quot;</li></ul><h3 id="handtering-af-følelsesmæssige-øjeblikke" tabindex="-1">Håndtering af følelsesmæssige øjeblikke <a class="header-anchor" href="#handtering-af-følelsesmæssige-øjeblikke" aria-label="Permalink to &quot;Håndtering af følelsesmæssige øjeblikke&quot;">​</a></h3><p><strong>Nogen græder under Fear in a Hat:</strong></p><ul><li>✅ Normaliser: &quot;Tårer er mod, ikke svaghed&quot;</li><li>✅ Tilbyd lommetørklæder, ikke forhast dig</li><li>✅ Spørg: &quot;Hvad har du brug for lige nu?&quot;</li><li>❌ Lad være med at: &quot;Det er okay, græd ikke&quot;</li></ul><p><strong>Konflikt mellem spillere:</strong></p><ul><li>✅ Pause og adressering</li><li>✅ &quot;Hvad sker der lige nu?&quot;</li><li>✅ Brug som læringsmoment</li><li>❌ Undlad at: Ignorer eller minimer</li></ul><p><strong>Nogen lukker ned:</strong></p><ul><li>✅ Indtjekning privat i pausen</li><li>✅ &quot;Jeg bemærkede, at du blev stille. Hvad sker der?&quot;</li><li>✅ Tilbudsmuligheder: deltag anderledes, tag en pause</li><li>❌ Undlad at: Råb ud offentligt</li></ul><h2 id="opfølgning-efter-lejren" tabindex="-1">Opfølgning efter lejren <a class="header-anchor" href="#opfølgning-efter-lejren" aria-label="Permalink to &quot;Opfølgning efter lejren&quot;">​</a></h2><h3 id="øjeblikkelig-24-48-timer" tabindex="-1">Øjeblikkelig (24-48 timer) <a class="header-anchor" href="#øjeblikkelig-24-48-timer" aria-label="Permalink to &quot;Øjeblikkelig (24-48 timer)&quot;">​</a></h3><p><strong>Send til alle deltagere:</strong></p><ul><li>Takkebesked</li><li>Opsummering af de vigtigste konklusioner</li><li>Billeder fra weekenden</li><li>Kontaktliste (med tilladelse)</li><li>Link til ressourcer på hjemmesiden</li></ul><p><strong>Individuelle indtjekninger:</strong></p><ul><li>Send en sms til alle, der har delt meget</li><li>&quot;Hvordan har du det med weekenden?&quot;</li><li>Håndter eventuelle sårbarhedsoverskud</li></ul><h3 id="kortvarig-2-uger" tabindex="-1">Kortvarig (2 uger) <a class="header-anchor" href="#kortvarig-2-uger" aria-label="Permalink to &quot;Kortvarig (2 uger)&quot;">​</a></h3><p><strong>Valgfri online session (60-90 min):</strong></p><ul><li>Hvordan har du anvendt læringen?</li><li>Hvad virker? Hvad er udfordrende?</li><li>Peer-støtte og problemløsning</li><li>Forstærk forpligtelser</li></ul><h3 id="langsigtet-1-3-maneder" tabindex="-1">Langsigtet (1-3 måneder) <a class="header-anchor" href="#langsigtet-1-3-maneder" aria-label="Permalink to &quot;Langsigtet (1-3 måneder)&quot;">​</a></h3><p><strong>Deltagere i undersøgelsen:</strong></p><ul><li>Hvad er anderledes i dit spil?</li><li>Hvilke værktøjer bruger du stadig?</li><li>Hvad ville gøre den næste lejr bedre?</li><li>Vil du anbefale det til andre?</li></ul><p><strong>Sporpåvirkning:</strong></p><ul><li>Konkurrenceresultater</li><li>Selvrapporteret selvtillid</li><li>Holddynamik</li><li>Fortsat engagement</li></ul><h2 id="tilpasning-til-forskellige-gruppestørrelser" tabindex="-1">Tilpasning til forskellige gruppestørrelser <a class="header-anchor" href="#tilpasning-til-forskellige-gruppestørrelser" aria-label="Permalink to &quot;Tilpasning til forskellige gruppestørrelser&quot;">​</a></h2><h3 id="lille-lejr-10-12-spillere" tabindex="-1">Lille lejr (10-12 spillere) <a class="header-anchor" href="#lille-lejr-10-12-spillere" aria-label="Permalink to &quot;Lille lejr (10-12 spillere)&quot;">​</a></h3><p><strong>Fordele:</strong></p><ul><li>Dybere deling</li><li>Mere individuel opmærksomhed</li><li>Stærkere bånd</li></ul><p><strong>Justeringer:</strong></p><ul><li>Enkelt gruppe for al teori</li><li>Mere tid pr. person til aktiviteter</li><li>Intimt konkurrenceformat</li></ul><h3 id="stor-lejr-16-20-spillere" tabindex="-1">Stor lejr (16-20 spillere) <a class="header-anchor" href="#stor-lejr-16-20-spillere" aria-label="Permalink to &quot;Stor lejr (16-20 spillere)&quot;">​</a></h3><p><strong>Fordele:</strong></p><ul><li>Forskellige perspektiver</li><li>Mere variation i konkurrencer</li><li>Stordriftsfordele</li></ul><p><strong>Justeringer:</strong></p><ul><li>Opdel i 2 grupper til nogle teoritimer</li><li>Behøver 2 MPC/facilitatorer</li><li>Større turneringsramme</li><li>Mere strukturerede rotationer</li></ul><h2 id="budgetovervejelser" tabindex="-1">Budgetovervejelser <a class="header-anchor" href="#budgetovervejelser" aria-label="Permalink to &quot;Budgetovervejelser&quot;">​</a></h2><h3 id="omsætning" tabindex="-1">Omsætning <a class="header-anchor" href="#omsætning" aria-label="Permalink to &quot;Omsætning&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Vare</th><th>Pris pr. person</th><th>20 personer</th><th>10 personer</th></tr></thead><tbody><tr><td><strong>Registrering</strong></td><td>150-250 €</td><td>3.000-5.000 €</td><td>1.500-2.500 €</td></tr></tbody></table><h3 id="udgifter" tabindex="-1">Udgifter <a class="header-anchor" href="#udgifter" aria-label="Permalink to &quot;Udgifter&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kategori</th><th>Omkostninger</th><th>Noter</th></tr></thead><tbody><tr><td><strong>Leje af faciliteter</strong></td><td>€500-1.000</td><td>Weekendpris</td></tr><tr><td><strong>Indkvartering</strong></td><td>€40-60/person/nat</td><td>Delte værelser</td></tr><tr><td><strong>Måltider</strong></td><td>€30-40/person/dag</td><td>6 måltider</td></tr><tr><td><strong>Personale</strong></td><td>€500-1.000</td><td>MPC + trænere</td></tr><tr><td><strong>Materialer</strong></td><td>100-200 €</td><td>Arbejdsark, forsyninger</td></tr><tr><td><strong>Præmier</strong></td><td>€100-200</td><td>Anerkendelsesgenstande</td></tr></tbody></table><p><strong>I alt pr. person:</strong> €120-180 <strong>Margin:</strong> €30-70/person (eller nulpunkt for fællesskabsopbygning)</p><h2 id="succesmalinger" tabindex="-1">Succesmålinger <a class="header-anchor" href="#succesmalinger" aria-label="Permalink to &quot;Succesmålinger&quot;">​</a></h2><h3 id="umiddelbare-indikatorer" tabindex="-1">Umiddelbare indikatorer <a class="header-anchor" href="#umiddelbare-indikatorer" aria-label="Permalink to &quot;Umiddelbare indikatorer&quot;">​</a></h3><ul><li>[ ] Psykologisk sikkerhedsscore (1-10 gennemsnit &gt;7)</li><li>[ ] Deltagelsesrate (&gt;80 % deler aktivt)</li><li>[ ] Fuldførelsesprocent (&gt;90 % opholder sig hele weekenden)</li><li>[ ] Tilfredshedsscore (gennemsnit 1-10 &gt;8)</li></ul><h3 id="langsigtede-indikatorer" tabindex="-1">Langsigtede indikatorer <a class="header-anchor" href="#langsigtede-indikatorer" aria-label="Permalink to &quot;Langsigtede indikatorer&quot;">​</a></h3><ul><li>[ ] Adfærdsændring (ved hjælp af værktøjer i konkurrencer)</li><li>[ ] Forbedring af præstation (selvrapporteret)</li><li>[ ] Opbygning af fællesskab (at holde kontakten)</li><li>[ ] Anbefalinger (anbefalinger til andre)</li></ul><h2 id="almindelige-fejl-der-skal-undgas" tabindex="-1">Almindelige fejl, der skal undgås <a class="header-anchor" href="#almindelige-fejl-der-skal-undgas" aria-label="Permalink to &quot;Almindelige fejl, der skal undgås&quot;">​</a></h2><p>::: fare Faldgruber <strong>1. For meget indhold</strong></p><ul><li>Forsøger at dække alt</li><li><strong>Rettelse:</strong> Fokus på dybde, ikke bredde</li></ul><p><strong>2. Springer refleksion over</strong></p><ul><li>Skynder sig til næste aktivitet</li><li><strong>Rettelse:</strong> Indbygget behandlingstid</li></ul><p><strong>3. Ignorerer modstand</strong></p><ul><li>At overvinde skepsis</li><li><strong>Løsning:</strong> Håndter det direkte med verbal aikido</li></ul><p><strong>4. Teknisk træning under teorien</strong></p><ul><li>Blanding af roller</li><li><strong>Rettelse:</strong> Tydelige grænser mellem MPC og teknisk træner</li></ul><p><strong>5. Ingen opfølgning</strong></p><ul><li>Weekenden slutter, læringen stopper</li><li><strong>Rettelse:</strong> Planlæg kontaktpunkter efter lejren :::</li></ul><h2 id="ressourcer" tabindex="-1">Ressourcer <a class="header-anchor" href="#ressourcer" aria-label="Permalink to &quot;Ressourcer&quot;">​</a></h2><h3 id="fra-denne-hjemmeside" tabindex="-1">Fra denne hjemmeside <a class="header-anchor" href="#fra-denne-hjemmeside" aria-label="Permalink to &quot;Fra denne hjemmeside&quot;">​</a></h3><ul><li><a href="./workshop">Workshopguide</a> - Detaljerede faciliteringsprotokoller</li><li><a href="./training-session">Guide til træningssession</a> - Til løbende træning</li><li><a href="./uddannelse/ernæring/">Ernæring</a> - Protokoller for konkurrencedagen</li><li><a href="./uddannelse/mental-styrke/">Mental styrke</a> - Indre spilkoncepter</li><li><a href="./uddannelse/mindfulness/">Mindfulness</a> - Nærværsteknikker</li><li><a href="./uddannelse/taktik/">Taktik</a> - Strategisk tænkning</li></ul><h3 id="anbefalet-læsning" tabindex="-1">Anbefalet læsning <a class="header-anchor" href="#anbefalet-læsning" aria-label="Permalink to &quot;Anbefalet læsning&quot;">​</a></h3><ul><li><em>Tennisens indre spil</em> af Timothy Gallwey</li><li><em>Tankegang</em> af Carol Dweck</li><li><em>Den frygtløse organisation</em> af Amy Edmondson</li></ul>',144))])}]]);export{g as __pageData,u as default};
